def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        t = op[1]

        # Remove expired entries
        expired_keys = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
        for k in expired_keys:
            del cache[k]

        if op[0] == 'put':
            key, value = op[2], op[3]

            # If key exists, remove it (will be re-added as most recent)
            if key in cache:
                del cache[key]
            # If cache is at capacity, evict least recently used
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add the new entry as most recently used
            cache[key] = (value, t)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, wt = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, wt)
                results.append(value)
            else:
                results.append(-1)

    return results

